const slider = document.querySelector('#coefficient');
const curve = document.querySelector('#curve');
const value = document.querySelector('#value');
const observation = document.querySelector('#observation');

function draw() {
  const a = Number(slider.value);
  const points = [];
  for (let pixel = 0; pixel <= 480; pixel += 2) {
    const x = (pixel - 240) / 44;
    points.push((pixel === 0 ? 'M' : 'L') + pixel + ' ' + (140 - 24 * a * x * x));
  }
  curve.setAttribute('d', points.join(' '));
  value.value = a.toFixed(1);
  observation.textContent = a === 0
    ? 'a = 0 时，图像变为水平直线，表达式退化为 y = 0。'
    : '开口向' + (a > 0 ? '上' : '下') + '。|a| 越大，抛物线越窄。';
}

slider.addEventListener('input', draw);
draw();
